-- 1. Créer la table app_defaults (données de référence de l'application)
CREATE TABLE IF NOT EXISTS public.app_defaults (
  key        text PRIMARY KEY,
  data       jsonb NOT NULL,
  updated_at timestamptz DEFAULT now(),
  label      text
);

-- 2. RLS : lecture publique (anon key), écriture admin seulement
ALTER TABLE public.app_defaults ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS "app_defaults_read_all" ON public.app_defaults;
CREATE POLICY "app_defaults_read_all" ON public.app_defaults
  FOR SELECT USING (true);

DROP POLICY IF EXISTS "app_defaults_write_auth" ON public.app_defaults;
CREATE POLICY "app_defaults_write_auth" ON public.app_defaults
  FOR ALL USING (true);

